async function main(ctx) {
  const input = ctx.input || {};
  const includeStats = ctx.lastOutputOf('__initial__')?.include_usage_stats !== false;
  const labelsResponse = input.body || {};
  const labels = labelsResponse.labels || [];

  const systemLabels = labels.filter(l => l.type === 'system');
  const customLabels = labels.filter(l => l.type === 'user');

  const result = {
    summary: {
      total: labels.length,
      system: systemLabels.length,
      custom: customLabels.length
    },
    system_labels: systemLabels.map(l => ({
      id: l.id,
      name: l.name,
      type: l.type,
      messagesTotal: includeStats ? (l.messagesTotal || 0) : undefined,
      messagesUnread: includeStats ? (l.messagesUnread || 0) : undefined
    })),
    custom_labels: customLabels.map(l => ({
      id: l.id,
      name: l.name,
      type: l.type,
      labelListVisibility: l.labelListVisibility,
      messageListVisibility: l.messageListVisibility,
      messagesTotal: includeStats ? (l.messagesTotal || 0) : undefined,
      messagesUnread: includeStats ? (l.messagesUnread || 0) : undefined
    }))
  };

  return result;
}

